  VALUES 
    (159::BIGINT, 'Linda profe, califica suave, el curso se lleva tranquilo si está al día con las tareas que deja por semana. Siempre intenta aclarar dudas y ayudarlo a uno en lo que pueda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Aspectos de calificación claros']::TEXT[], '2026-07-17T00:00:00+00:00'::TIMESTAMPTZ, 'd25a7f0d21d36104f8d1baf77f44548dc0cb4d29f1f92d3813e7bde12a36d2e5'::TEXT, ARRAY[2432]::BIGINT[]),
    (159::BIGINT, 'Muy buena profe, es un amor literalmente, califica suave y las evaluaciones son muy fáciles, explica muy bien la materia y es de esos profes que les gusta enseñar, 100% recomendada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2026-06-28T00:00:00+00:00'::TIMESTAMPTZ, '4a7a7cc8a0003f20a9223dcc06bcc147c12abc2ef3d6c2ac109389a9e495d57f'::TEXT, ARRAY[625]::BIGINT[]),
    (159::BIGINT, 'Un amor de profe. En general con ir a las clases y responderle cuando le pregunte, el curso ya se pasa. Es bastante amable y hace que las clases se sientan amenas. El proyecto es hacer un video grabado hablando en ingles bastante sencillo. Recomendada y muy comoda, poca carga academica'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'a051ded17efe8dfb25a63ebc71005c1960a1794f43fb94564241fc07f60605c3'::TEXT, ARRAY[625]::BIGINT[]),
    (159::BIGINT, 'La mejor profe para llevar el curso, es súper amorosa y siempre está dispuesta a ayudar'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-11-29T00:00:00+00:00'::TIMESTAMPTZ, '6133d5ff1f19ab09b4f3f8562191f0dec3fafb6a91603f5f84adf69c51adf3c4'::TEXT, ARRAY[625]::BIGINT[]),
    (159::BIGINT, 'Sin dudas la mejor profesora de inglés que tuve en toda mi vida. Amable dentro y fuera del aula, no son difíciles sus clases y tiene muchísima paciencia.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-17T00:00:00+00:00'::TIMESTAMPTZ, '358d163a4927a0e9220a9e790a7c628038e513da5d8362afb5f74125f625bd61'::TEXT, ARRAY[625]::BIGINT[]),
    (159::BIGINT, 'Es un amor de persona, tiene un trato muy especial'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-04T00:00:00+00:00'::TIMESTAMPTZ, '74f15075e59b4f401f34011dbe2517b21a6bb112bdcabf6c8a31309b4ad57b1a'::TEXT, ARRAY[625]::BIGINT[]),
    (159::BIGINT, 'EXCELENTE PROFESORA, si tiene que llevar ingles II o otro ingles es la mejor opción de profe. Ayuda demasiado y es muy comprensiva si uno es muy respetuoso y sincero con ella. Si cumple con toda la evaluación del curso se pasa fácil. La asistencia es obligatoria. Faltan profes así ?'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2025-06-13T00:00:00+00:00'::TIMESTAMPTZ, '9f0c6a82aa23081b53916f66a82fa911074e065ba1147692819b4f4e581831c5'::TEXT, ARRAY[625]::BIGINT[]),
    (159::BIGINT, 'La recomiendo es super amable, explica bastante bien aunque puede llegar a ser aburrido. Siempre tendrá que participar en clase pero nada muy difícil. Los quizzes son sencillos y es literalmente lo que se pregunta en clase, si tiene la oportunidad de matricular con ella no la desperdicie!!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Brinda apoyo']::TEXT[], '2024-11-29T00:00:00+00:00'::TIMESTAMPTZ, '4d85417ebbb90fc8893d3a74dfe8069a3ba92d0e8f4a0b722683ee55ee4036ba'::TEXT, ARRAY[625]::BIGINT[]),
    (159::BIGINT, 'muy chill y amable, recomendada :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2024-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'bfb10d74c5b0a656447da2ebb207e16c9977015772d3a8c3f75ca88f5ff67fac'::TEXT, ARRAY[625]::BIGINT[]),
    (159::BIGINT, 'Es muy buena profe siempre se preocupa por los estudiantes, las clases aveces son un poco aburridas'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2024-11-21T00:00:00+00:00'::TIMESTAMPTZ, '3666f3a6791e4a72294d270e048dec059eafbdeaa3c304b7185b3de40a3e37d2'::TEXT, ARRAY[2433]::BIGINT[]),
    (159::BIGINT, 'La profe es super buena y hace la clase muy facil, claro en clase siempre se va a esperar que usted participe y hable frente a los demas pero nada de otro mundo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo']::TEXT[], '2024-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'c18acc8249c933a71f357df017144eddd7a06f29d46bb1cf0cb9c13156906070'::TEXT, ARRAY[2432]::BIGINT[]),
