    (159::BIGINT, 'Un amor de persona, el curso es muy fácil, y brinda apoyo cuando lo necesiten. Si pueden matriculen con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-12-01T00:00:00+00:00'::TIMESTAMPTZ, '3ddd1c2f9a921c72011d95c9f060e1570e20be5f67318d2f24d96845c2ae8572'::TEXT, ARRAY[625]::BIGINT[]),
    (159::BIGINT, 'Lo más fácil que se va a encontrar en Inglés, hace que el curso sea de medio crédito.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Pocos exámenes']::TEXT[], '2023-11-30T00:00:00+00:00'::TIMESTAMPTZ, '53f0ecf7e50e90323d48ddde04b0197c2989d5364f3be3d83d74ef3cfb29abec'::TEXT, ARRAY[625]::BIGINT[]),
    (159::BIGINT, 'La profe es demasiado linda, no hay un ser humano mejor que ella, es de lo más tranquila y el curso es súper relajado. No exige, califica de lo más bien, siempre está dispuesta a ayudar, no sé ella es tan linda de verdad. Enseña muy bien y su método de dar la clase no es exigente, la mejor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-11-13T00:00:00+00:00'::TIMESTAMPTZ, '43b8169827317993887077da1b65987f96c7708ef82be194f3a3ad894fb41860'::TEXT, ARRAY[625]::BIGINT[]),
    (159::BIGINT, 'Una teja, no lo dude, viva feliz'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '945c0cba96326902ea2ba32a514578f04ac7eca32a522a0aab87638df0af39b6'::TEXT, ARRAY[625]::BIGINT[]),
    (159::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'e19c4f29a9207f9e35d63edc8ecf08bb4b0d483ccc446541a81d72bf75636499'::TEXT, ARRAY[545]::BIGINT[]),
    (159::BIGINT, 'La profe es super accesible para aclarar dudas y explica muy bien. Lo único enredadillo puede ser algunos items de las tareas que deja semanalmente, pero yo la full recomiendo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2022-07-11T00:00:00+00:00'::TIMESTAMPTZ, '726ea1e6a1031599c0fe81fc386626ace43f7b576a1a55d08078ada8877f46cf'::TEXT, ARRAY[545]::BIGINT[]),
    (159::BIGINT, 'Las clases son cortas, pero explica muy bien y se aprende bastante, deja una tarea semanalmente, pero la puede hacer en menos de 10 min, los exámenes y exposiciones son DEMASIADO fáciles. No dude en matricular con ella.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'a253be276c1d14a7c3f7aaa2cd7f6531eb4d9df12d34bb50746d627bff833983'::TEXT, ARRAY[545]::BIGINT[]),
    (159::BIGINT, 'Es una profesora excelente, explica muy claro y despacio para las personas que no comprenden muy bien el inglés, y se encarga de que todos participen en clase con preguntas aleatorias, para nada complicadas. Es muy pendiente y anuente a responder cualquier tipo de duda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Pocos exámenes']::TEXT[], '2022-05-09T00:00:00+00:00'::TIMESTAMPTZ, '1cf6bb04f5dbe4c4ca012307d74feb9d32a8780d43ecfa2be8aff008b46015f6'::TEXT, ARRAY[545]::BIGINT[]),
    (159::BIGINT, 'La profe es un amor y explica super bien, pasar es fácil, deja una evaluación semanal pero se hace fácil en media hora, los quizes orales y escritos también son fáciles'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-07T00:00:00+00:00'::TIMESTAMPTZ, '7b135e38c9a11a5ab73a0c91e36cacb956a1f9fe3fb05c1fb303a64b8928d3e4'::TEXT, ARRAY[625]::BIGINT[]),
    (159::BIGINT, 'Es muy fácil pasar con ella, la recomiendo al 100% y diría que es la mejor de la escuela.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, '85fae9a4fac0fd9252b2afaf31010c843f427895e042da2ed1a4137cfebe3d59'::TEXT, ARRAY[625]::BIGINT[]),
