    (159::BIGINT, 'Excelente profe, las clases son cortas y son al grano, si le gusta que todos participen.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-25T00:00:00+00:00'::TIMESTAMPTZ, '65061e54bfbf8c249720407fd97908ee015f64cda763170cbe9539baf7a14b82'::TEXT, ARRAY[625]::BIGINT[]),
    (159::BIGINT, 'Super buena profe y amable. Le gusta que todos participen'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-22T00:00:00+00:00'::TIMESTAMPTZ, '1ff65287a5dc4f9fdb732a5f8448b371b2b9ef2b63101efaa515d0c4a315afc9'::TEXT, ARRAY[625]::BIGINT[]),
    (159::BIGINT, 'El curso es bastante fácil si sabe lo básico. La asistencia no es obligatoria, graba las clases y las tareas fáciles y cortas. Deja un proyecto al final que se saca rápido y como 2 quices orales'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, '9a9191a3436ad8a303bbeca83a6c379cf57f786a8322b4d8bbc08c12f1a3f937'::TEXT, ARRAY[625]::BIGINT[]),
