    (159::BIGINT, 'La profe es muy amable pero hace muchas evaluaciones orales y eso dificulta el curso'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2021-07-06T00:00:00+00:00'::TIMESTAMPTZ, '0c533c811a849553f2ae6390bdd985338f09c94026e804af5369d244a8be26b6'::TEXT, ARRAY[545]::BIGINT[]),
    (159::BIGINT, 'Explica bastante bien, tomando en cuenta que es un curso muy básico del idioma. Los trabajos son cortos y fáciles. No califica para nada duro, siempre pone el 100 en todos los trabajos que evalúan la parte oral. El curso se pasa muy fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-25T00:00:00+00:00'::TIMESTAMPTZ, '0c124923e485062c30e30e3b8b6aab3eea9ac4dfc10dc77d19c978d5be3723c6'::TEXT, ARRAY[625]::BIGINT[]),
