    (159::BIGINT, 'Deja demasiados trabajos y hace que los dos créditos sean como cuatro. Mejor matricule con otra persona.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-02T00:00:00+00:00'::TIMESTAMPTZ, 'b5e85a56c2e1e1a9c1d258af2c4455b081f7ff89dbf0663a3d2c95bc71f5ee63'::TEXT, ARRAY[625]::BIGINT[]),
    (159::BIGINT, 'Buena profe, las clases cortas y al grano; y si uno necesita ayuda, la brinda sin problema'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, '9b6917e6383c131a90257153ea3c475113ea330a74dc5d3a3772d051b769d3fc'::TEXT, ARRAY[625]::BIGINT[]),
    (159::BIGINT, 'Excelente profesora, la recomiendo las clases virtuales no eran extensas, era muy atenta y amable.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-12-24T00:00:00+00:00'::TIMESTAMPTZ, '1f65620a9f5820bf4f3a246949fb63f10831bcbb5fce96829cc5a97c80e5ea4e'::TEXT, ARRAY[539]::BIGINT[]),
    (159::BIGINT, 'La profe Mabel es lo mejor que puede existir, explica y hace las cosas con un amor. Profe Mabel si ves esto quiero que sepas que estoy ENAMORADO de usted.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-31T00:00:00+00:00'::TIMESTAMPTZ, '4eea986d2cb770d67ec7d400164b95444ad6a38c105e85090b400b791e05ccf2'::TEXT, ARRAY[2432, 625, 2433]::BIGINT[]),
    (159::BIGINT, 'La profe es un amor, las tareas que deja son fáciles de hacer y ayudan a ir adquiriendo vocabulario, es comprensiva si uno tuvo algún inconveniente con alguna evaluación, además de ser la profesora más dulce que he tenido en todos mis años de estudiante'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-29T00:00:00+00:00'::TIMESTAMPTZ, 'c7009a29ed16f2774cb34814e02672ffa1f808a5f15b5877a4e6194c69297ea5'::TEXT, ARRAY[2432, 625, 2433]::BIGINT[]),
    (159::BIGINT, 'Es un amor de profe. Explica tranquila y se le entiende perfectamente. Las tareas que deja son fáciles y permiten ejercitar el lenguaje de una forma más dinámica.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-12-22T00:00:00+00:00'::TIMESTAMPTZ, '744f2bcaa2697b222950b2cc819aba23a9362ea4d9139b01d6313d9747926685'::TEXT, ARRAY[545]::BIGINT[]),
    (159::BIGINT, 'La profe es un amor de persona, ya es el segundo curso que llevé con ella. Califica suave y te da apoyo. Deja trabajos largos (porque lo llevé semivirtual). Deja salir antes de la hora y hace presentaciones para poder practicar, los exámenes son muy fáciles(como el libro) y se pasa con buena nota :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2019-06-27T00:00:00+00:00'::TIMESTAMPTZ, '10aad9539b4f1c9ed26abc4b4239395a41080e0d4f7338dd774c9a8dab6d2d22'::TEXT, ARRAY[2432]::BIGINT[]),
    (159::BIGINT, 'La profe es súper linda y considerada, califica normal y hace presentaciones casi cada semana. Se practica bastante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'eb3c1b0835b86aca1c4dbda5613dc73a68fdc8a84882a8b3b6c3ca1a473e7f51'::TEXT, ARRAY[545]::BIGINT[]),
    (159::BIGINT, 'Muy buena profe, hace el curso muy fácil. Hace muchas exposiciones que es lo que más toma tiempo pero en general son muy faciles.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'da952abc4aedaab25b897e4cf9c55ef3fd042a471ab774440f94e60d241694f6'::TEXT, ARRAY[545]::BIGINT[]),
    (159::BIGINT, 'Muy buena profe, aclara las dudas siempre y explica muy bien, recomiendo matricular con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '442748e194a09848123029af8da820a8f2c84074f63a1425c27ead6715e90af4'::TEXT, ARRAY[2432, 625, 2433]::BIGINT[]),
    (159::BIGINT, 'Es demasiado buena profe, super buena gente, si pueden, metan con ella, es demasiado linda como persona'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-08T00:00:00+00:00'::TIMESTAMPTZ, '480700a07b7bc6eac9870f28dfa902e0fe67d0c1362d8616ea25942e42bd60c7'::TEXT, ARRAY[545]::BIGINT[]),
    (159::BIGINT, 'La mejor profe, es demasiado dulce, uno llega a tenerle cariño. Deja exposiciones cada nada pero eso es bueno para aprender a hablar en público y practicar el inglés. Los exámenes son demasiado fáciles. Se pasa con excelente nota.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-05-29T00:00:00+00:00'::TIMESTAMPTZ, '9da25e9bc86cfabf5c16b3122be3ed597b560a0b659d2c46460badeb02782a40'::TEXT, ARRAY[545]::BIGINT[]),
    (159::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-03T00:00:00+00:00'::TIMESTAMPTZ, 'e888d2724059f78bbc8e0fd126cc45755986d20e76d02f11bcd8e32efda3da34'::TEXT, ARRAY[625]::BIGINT[]),
    (159::BIGINT, 'una de las profesores más dulces que hay en el tec. es muy linda y da la clase muy claro. hay que hacer muchas presentaciones, pero no califica duro.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases largas', 'Clases excelentes']::TEXT[], '2018-11-28T00:00:00+00:00'::TIMESTAMPTZ, '51fbd76a5053fd393c557bb81ac8b3d954582ddbaecf79435dfd5993f668b2d8'::TEXT, ARRAY[625]::BIGINT[]),
    (159::BIGINT, 'Demasiado linda y dulce, califica súper suave, pero deja DEMASIADOS trabajos, exposiciones casi cada semana. Si el grupo es chill y le da igual hablar en público en inglés, meta sin miedo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-23T00:00:00+00:00'::TIMESTAMPTZ, '67958802ece6e6f4eaf26990a330401680cdfe4a10a0c7656e21820d13cfa120'::TEXT, ARRAY[625]::BIGINT[]),
    (159::BIGINT, 'Buena persona, dulce Como profersora califica suave, te deja un par de tareas muy recomendada'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-13T00:00:00+00:00'::TIMESTAMPTZ, '91b49e807136fde9f4edef23d72bc2f823015e26b10ceaabb1088128a1d9090b'::TEXT, ARRAY[625]::BIGINT[]),
    (159::BIGINT, 'Muy buena Profe'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '1a8d8b921a39a75bf19a260260db78475f664d557eae4c5d2aef41de83e98318'::TEXT, ARRAY[625]::BIGINT[]),
    (159::BIGINT, 'Es muy fácil pasar con ella, se preocupa porque los estudiantes entiendan la materia. Siempre deja tarea pero se hace en 5 minutos. Muchas exposiciones (se puede improvisar). La participación importa. Es muy comprensible, si ocupa faltar por algo importante solo hable con ella. Súper recomendada????????'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2018-06-20T00:00:00+00:00'::TIMESTAMPTZ, '8069335f80964f8baa9f6ebd6c173abec294f9d6176a6e824663944ecf3becf8'::TEXT, ARRAY[545]::BIGINT[]),
    (159::BIGINT, 'Muy comprensiva y cariñosa, las clases son un poco mecánicas y pueden volverse aburridas. Creo que hace falta más actividades en clase para hablar en inglés. Deja tareas para ayudarle a repasar, son muy fáciles y los exámenes también son muy sencillos.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-07T00:00:00+00:00'::TIMESTAMPTZ, '72fe16bda90d98045951ddbd08e4fadddd49e14078551bab2fa0e548326bc64b'::TEXT, ARRAY[625]::BIGINT[]),
    (159::BIGINT, 'Es muy dulce y preocupada por sus estudiantes. Pone muchas tareas que se hacen como en cinco minutos, así que el curso se pasa fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2017-06-18T00:00:00+00:00'::TIMESTAMPTZ, '2820d7d731f67e3b14dfb4071f7945e28a271df0c0b8d84c9e72179096c585d8'::TEXT, ARRAY[547]::BIGINT[]),
    (159::BIGINT, 'Es súper linda, muy comprensiva, si tenés algo importante, podés hablar para que te lo reponga. Recomendada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, '53095d0173f5d74a677fc703a444f83efad7fcaf521352c65c1ff5adefb947a1'::TEXT, ARRAY[545]::BIGINT[]),
    (159::BIGINT, 'La profe es un amor y se esfuerza mucho para que uno entienda. Nada más que deja muchas exposiciones pero los temas son muy sencillos, incluso se puede improvisar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2017-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'b6689947678157b69e6865e28884ed9b5af52e6b7a5f30290987227156d93464'::TEXT, ARRAY[2432, 625, 2433]::BIGINT[]),
    (159::BIGINT, 'Es una excelente profe, se preocupa de que el estudiante entienda la materia, le gusta que uno participe y siempre deja tareas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-02-03T00:00:00+00:00'::TIMESTAMPTZ, '7b344a9951e016e8a17194eaf43ef214ba20c108200ab2e8a231d195fe78940f'::TEXT, ARRAY[625]::BIGINT[]),
