    (159::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'a3efbb366d2032736940ae080e0dc8d41615e2b3cf6d13badf9f638b0ca5f8a7'::TEXT, ARRAY[545]::BIGINT[]),
    (159::BIGINT, 'Es súper bella gente, califica suave, muy buena persona. Uno se siente como en familia con ella es muy linda y el curso se pasa con excelente nota.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-27T00:00:00+00:00'::TIMESTAMPTZ, '6cc918b2599a1a06488552cfc13814a1107cbdb015f0db04252fb1731de4f648'::TEXT, ARRAY[545]::BIGINT[]),
    (159::BIGINT, 'Excelente persona y profesora. Se aprende mucho'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-23T00:00:00+00:00'::TIMESTAMPTZ, '9cd82b438df751eb1a063840316d8a3dd616f8bcb77af049782e5d05e679a853'::TEXT, ARRAY[2432]::BIGINT[]),
    (159::BIGINT, 'Excelente profesora, uno aprende en un ambiente muy tranquilo y acogedor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'b14a4d0453e3176fe12841ca67db7cf975fbf567d2de2e2af4d60e7a8aaa6a63'::TEXT, ARRAY[545]::BIGINT[]),
    (159::BIGINT, 'Excelente profe, una gran persona , califica suave y repite mas de 2 veces el famoso y aveces matador "listening" recomendada 100%'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '7cac635a0ad0c3bb7f28b1dd941c6517f5ba3cdaaaa98f052c4000a8cdbaf3b8'::TEXT, ARRAY[625]::BIGINT[]),
    (159::BIGINT, 'Es muy buena, excelente persona y se aprende bastante. Califica muy suave. Recomendadísima'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-11T00:00:00+00:00'::TIMESTAMPTZ, 'a725bf46201897ba210144cace68df511cfc21c900d9aa27e8d85cc136c4b532'::TEXT, ARRAY[545]::BIGINT[]),
